"""Status validation and job transition rules."""

VALID_STATUSES = ["NEW", "ACTIVE", "DONE"]

TRANSITIONS = {
    "NEW": ["ACTIVE"],
    "ACTIVE": ["DONE"],
    "DONE": [],
}


def normalize_status(status: str) -> str:
    """Return a canonical status value or raise ValueError."""
    if not isinstance(status, str):
        raise ValueError("status must be a valid status string")
    normalized = status.strip().upper()
    if normalized not in VALID_STATUSES:
        raise ValueError("invalid status: " + str(status))
    return normalized


def can_transition(old: str, new: str) -> bool:
    """Return whether a status may change from *old* to *new*."""
    old_status = normalize_status(old)
    new_status = normalize_status(new)
    return old_status == new_status or new_status in TRANSITIONS[old_status]
